/* ── 假数据源（行为是真的：1 Hz 推进、暂停停表、结束时入库）──────── */
typedef struct {
    bool active;
    bool paused;        /* 手动或自动暂停中（计时/里程/均速都停） */
    bool auto_paused;   /* 本次暂停由自动暂停触发 */
    int still_s;        /* 速度低于阈值的连续秒数 */
    uint32_t elapsed_s;
    double t;
    double dist_km;
    double speed;
    double target;      /* 未受暂停门控的速度（自动暂停判定用） */
    double avg;
    double max;
    int hr;
    int cadence;
    int power;
    int elevation;
    int ascent;
    int cal;
    int hist[5];
    uint32_t seed;
} ride_t;

