static void ride_refresh(void)
{
    char buf[32];

    if (UR.arc == NULL) {
        return;
    }
    lv_arc_set_value(UR.arc, (int)lround(R.speed));
    snprintf(buf, sizeof(buf), "%.1f", conv_speed(R.speed));
    lv_label_set_text(UR.hero, buf);
    lv_obj_set_style_text_color(UR.hero,
                                lv_color_hex(R.paused ? P_TRACK : P_INK), 0);
    if (UR.unit != NULL) {
        lv_label_set_text(UR.unit, unit_speed());
        lv_obj_set_style_text_color(UR.unit,
                                    lv_color_hex(R.paused ? P_TRACK : P_MUTE),
                                    0);
    }
    snprintf(buf, sizeof(buf), "%d", R.hr);
    if (UR.hr_val != NULL) {
        lv_label_set_text(UR.hr_val, buf);
    }
    {
        int x = 64 + (int)lround(152.0 * R.speed / 60.0) - 1;

        if (x < 65) x = 65;
        if (x > 212) x = 212;
        lv_obj_set_x(UR.cursor, x);
    }
    {
        const int z = hr_zone(R.hr);
        static const uint32_t zc[5] = { 0xD6D2CEu, 0xCED7E6u, 0xC5DBCEu,
                                        0xEFD7C5u, 0xE8CCC4u };
        static const uint32_t zd[5] = { 0x8F8A7Fu, 0x1C63B0u, 0x0B6E4Fu,
                                        0xBD5908u, 0xA62B1Fu };

        for (int i = 0; i < 5; i++) {
            lv_obj_set_style_bg_color(UR.hr[i],
                                      lv_color_hex(i == z - 1 ? zd[i] : zc[i]),
                                      0);
        }
        lv_obj_set_x(UR.hr_b1, 64 + (z - 1) * 152 / 5);
        lv_obj_set_x(UR.hr_b2, 64 + z * 152 / 5);
        snprintf(buf, sizeof(buf), "心率 Z%d", z);
        lv_label_set_text(UR.hr_z, buf);
    }
    {
        const char *vals[4];
        char b0[24], b1[24], b2[24], b3[24];

        if (s_ride_page == 0) {
            snprintf(b0, sizeof(b0), "%.1f", conv_dist(R.dist_km));
            snprintf(b1, sizeof(b1), "%u:%02u",
                     (unsigned)(R.elapsed_s / 60),
                     (unsigned)(R.elapsed_s % 60));
            snprintf(b2, sizeof(b2), "%d", R.cadence);
            snprintf(b3, sizeof(b3), "%d", R.elevation);
            vals[0] = b0; vals[1] = b1; vals[2] = b2; vals[3] = b3;
        } else if (s_ride_page == 1) {
            snprintf(b0, sizeof(b0), "%.1f", conv_speed(R.avg));
            snprintf(b1, sizeof(b1), "%.1f", conv_speed(R.max));
            snprintf(b2, sizeof(b2), "%d", R.power);
            snprintf(b3, sizeof(b3), "%d", R.ascent);
            vals[0] = b0; vals[1] = b1; vals[2] = b2; vals[3] = b3;
        } else {
            snprintf(b0, sizeof(b0), "%d", R.hr);
            snprintf(b1, sizeof(b1), "Z%d", hr_zone(R.hr));
            snprintf(b2, sizeof(b2), "%.1f", conv_speed(R.avg));
            snprintf(b3, sizeof(b3), "%d", R.cadence);
            vals[0] = b0; vals[1] = b1; vals[2] = b2; vals[3] = b3;
        }
        for (int i = 0; i < 4; i++) {
            lv_label_set_text(UR.metrics[i], vals[i]);
        }
    }
    for (int i = 0; i < 3; i++) {
        lv_obj_set_style_bg_color(UR.dots[i],
                                  lv_color_hex(i == s_ride_page ? C_DEEP[M_RIDE]
                                                                : P_TRACK),
                                  0);
    }
}

static void ride_page_types(void)
{
    char lab[4][24];

    if (s_ride_page == 0) {
        snprintf(lab[0], sizeof(lab[0]), "里程 %s", unit_dist());
        snprintf(lab[1], sizeof(lab[1]), "时间");
        snprintf(lab[2], sizeof(lab[2]), "踏频 rpm");
        snprintf(lab[3], sizeof(lab[3]), "海拔 m");
    } else if (s_ride_page == 1) {
        snprintf(lab[0], sizeof(lab[0]), "均速 %s", unit_speed());
        snprintf(lab[1], sizeof(lab[1]), "最大 %s", unit_speed());
        snprintf(lab[2], sizeof(lab[2]), "功率 W");
        snprintf(lab[3], sizeof(lab[3]), "爬升 m");
    } else {
        snprintf(lab[0], sizeof(lab[0]), "心率 bpm");
        snprintf(lab[1], sizeof(lab[1]), "区间");
        snprintf(lab[2], sizeof(lab[2]), "均速 %s", unit_speed());
        snprintf(lab[3], sizeof(lab[3]), "踏频 rpm");
    }

    /* 270° 仪表：中心 (120,106)、d=152、7px（与盘面收缩后的几何对位）。 */
    arc = lv_arc_create(s_scr);
    lv_obj_set_size(arc, 152, 152);
    lv_obj_set_pos(arc, 44, 30);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_all(arc, 0, 0);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(arc, 0, 0);
    lv_obj_set_style_outline_width(arc, 0, 0);
    lv_obj_set_style_shadow_width(arc, 0, 0);
    lv_obj_set_style_arc_width(arc, 7, LV_PART_MAIN);
    lv_obj_set_style_arc_color(arc, lv_color_hex(P_TRACK), LV_PART_MAIN);
    lv_obj_set_style_arc_rounded(arc, true, LV_PART_MAIN);
    lv_obj_set_style_arc_width(arc, 7, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(arc, lv_color_hex(C_DEEP[M_RIDE]),
                               LV_PART_INDICATOR);
    lv_obj_set_style_arc_rounded(arc, true, LV_PART_INDICATOR);
    lv_obj_set_style_bg_color(arc, lv_color_hex(P_INK), LV_PART_KNOB);
    lv_obj_set_style_bg_opa(arc, LV_OPA_COVER, LV_PART_KNOB);
    lv_obj_set_style_border_width(arc, 0, LV_PART_KNOB);
    lv_obj_set_style_pad_all(arc, 3, LV_PART_KNOB);
    lv_arc_set_bg_angles(arc, 0, 270);
    lv_arc_set_rotation(arc, 135);
    lv_arc_set_range(arc, 0, 60);
    lv_arc_set_value(arc, (int)lround(R.speed));
    UR.arc = arc;

    for (int i = 0; i < 7; i++) {
        lv_point_precise_t pts[2];
        const double a = (double)(225 + i * 45) * DEG2RAD;

        pts[0].x = 120 + (int)lround(sin(a) * 78);
        pts[0].y = 106 - (int)lround(cos(a) * 78);
        pts[1].x = 120 + (int)lround(sin(a) * 84);
        pts[1].y = 106 - (int)lround(cos(a) * 84);
        (void)LINE(s_scr, pts, 2, 1, P_TICK);
    }

    /* hero：容器整体做 0→100% 淡入（ANIMATION #3 的阶段 C）。 */
    hero_box = lv_obj_create(s_scr);
    lv_obj_remove_style_all(hero_box);
    lv_obj_set_pos(hero_box, 40, 64);
    lv_obj_set_size(hero_box, 160, 72);
    lv_obj_remove_flag(hero_box, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_remove_flag(hero_box, LV_OBJ_FLAG_CLICKABLE);
    UR.hero_box = hero_box;
    {
        lv_obj_t *stack = d_stack(hero_box, 0, 0, 160, 56,
                                  LV_FLEX_ALIGN_CENTER, 0);

        UR.hero = lv_label_create(stack);
        lv_obj_set_style_text_font(UR.hero, F(PX_HERO), 0);
        lv_obj_set_style_text_color(UR.hero,
                                    lv_color_hex(R.paused ? P_TRACK : P_INK), 0);
    }
    UR.unit = LW(hero_box, unit_speed(), PX_SMALL, P_MUTE, 0, 56, 160,
                 LV_TEXT_ALIGN_CENTER);

    /* 两行“标签 + 条”共用同一几何：标签列 x=24..64（40 px，容得下
     * “心率 Z4” 37 px 墨迹 + 2 px 间隙），色带 x=64..216（宽 152）。
     * 速度带 76/38/38 = 0-30/30-45/45-60；心率带按 152/5 取整分五段。 */
    {
        const int x0 = 64, w = 152, w1 = 76, w2 = 38;

        L(s_scr, "速度", PX_MICRO, P_MUTE, 24, 186);
        (void)B(s_scr, x0, 184, w1, 18, C_LIGHT[M_NAV], LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1, 184, w2, 18, C_LIGHT[M_RIDE],
                LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1 + w2, 184, w2, 18, C_LIGHT[M_RECORD],
                LV_OPA_COVER, 0);
        (void)B(s_scr, x0, 184, w1, 2, C_DEEP[M_NAV], LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1, 184, w2, 2, C_DEEP[M_RIDE], LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1 + w2, 184, w2, 2, C_DEEP[M_RECORD],
                LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1, 184, 1, 18, P_INK, LV_OPA_COVER, 0);
        (void)B(s_scr, x0 + w1 + w2, 184, 1, 18, P_INK, LV_OPA_COVER, 0);
        {
            char b[8];

            L(s_scr, "0", PX_MICRO, P_INK, x0 + 4, 186);
            snprintf(b, sizeof(b), "%.0f", conv_speed(30.0));
            L(s_scr, b, PX_MICRO, P_INK, x0 + w1 + 3, 186);
            snprintf(b, sizeof(b), "%.0f", conv_speed(60.0));
            L(s_scr, b, PX_MICRO, P_INK, x0 + w - 16, 186);
        }
        UR.cursor = B(s_scr, x0 + (int)lround(w * R.speed / 60.0) - 1, 182,
                      3, 22, P_INK, LV_OPA_COVER, 1);
    }

    /* 心率行拆成两行（WP-HELM5）：
     *   第 1 行 标签列 x=24..64 + “148” 22px 值盒 x=96,w=90（像素 96..185，右对齐）
     *          + “bpm” 12px 单位盒 x=190,w=26（像素 190..215，右对齐到 216）；
     *   第 2 行 5 分区色带 x=64,w=152（像素 64..215，与速度带同 x0/x1/宽）。
     * 竖直：速度带止于 201，值墨迹 204..220，色带 224..243。 */
    {
        static const uint32_t zc[5] = { 0xD6D2CEu, 0xCED7E6u, 0xC5DBCEu,
                                        0xEFD7C5u, 0xE8CCC4u };
        const int x0 = 64, w = 152;

        UR.hr_z = L(s_scr, "心率 Z4", PX_MICRO, P_MUTE, 24, 205);
        UR.hr_val = LW(s_scr, "142", PX_VALUE, P_INK, 96, 199, 90,
                       LV_TEXT_ALIGN_RIGHT);
        LW(s_scr, "bpm", PX_SMALL, P_MUTE, 190, 206, 26,
           LV_TEXT_ALIGN_RIGHT);
        for (int i = 0; i < 5; i++) {
            const int bx = x0 + i * w / 5;
            const int bw = x0 + (i + 1) * w / 5 - bx;

            UR.hr[i] = B(s_scr, bx, 224, bw, 20,
                         i == 3 ? C_DEEP[M_RECORD] : zc[i], LV_OPA_COVER, 0);
        }
        for (int i = 1; i < 5; i++) {
            (void)B(s_scr, x0 + i * w / 5, 224, 1, 20, P_TICK,
                    LV_OPA_COVER, 0);
        }
        UR.hr_b1 = B(s_scr, x0 + 3 * w / 5, 224, 1, 20, P_INK,
                     LV_OPA_COVER, 0);
        UR.hr_b2 = B(s_scr, x0 + 4 * w / 5, 224, 1, 20, P_INK,
                     LV_OPA_COVER, 0);
    }

