/** 心率行右侧迷你曲线（填法 A）刷新：31 点、量程自适应、末端方点。 */
static void hr_spark_refresh(void)
{
    int v[HR_SPARK_N];
    int lo = 1000;
    int hi = -1000;
    int pad;

    if (UR.hr_spark == NULL) {
        return;
    }
    for (int i = 0; i < HR_SPARK_N; i++) {
        v[i] = R.hr + s_hr_delta[i];
        if (v[i] < HR_MIN_BPM) v[i] = HR_MIN_BPM;
        if (v[i] > HR_MAX_BPM) v[i] = HR_MAX_BPM;
        if (v[i] < lo) lo = v[i];
        if (v[i] > hi) hi = v[i];
    }
    pad = (hi - lo) / 6;
    if (pad < 4) pad = 4;
    lo -= pad;
    hi += pad;
    if (hi <= lo) hi = lo + 1;
    for (int i = 0; i < HR_SPARK_N; i++) {
        const int inner = HR_SPARK_H - 2 * HR_SPARK_PAD - 1;

        s_hr_spark_pts[i].x = HR_SPARK_X0 +
            (int)lround((double)i * (HR_SPARK_X1 - HR_SPARK_X0) /
                        (HR_SPARK_N - 1));
        s_hr_spark_pts[i].y = HR_SPARK_Y + HR_SPARK_PAD +
            (int)lround((double)(hi - v[i]) * inner / (double)(hi - lo));
    }
    lv_line_set_points(UR.hr_spark, s_hr_spark_pts, HR_SPARK_N);
    if (UR.hr_dot != NULL) {
        lv_obj_set_pos(UR.hr_dot, s_hr_spark_pts[HR_SPARK_N - 1].x - 1,
                       s_hr_spark_pts[HR_SPARK_N - 1].y - 1);
    }
}

